mapper.select:
SELECT R.REPORT_NO, R.REPORT_TYPE, R.COMMUNITY_NO, R.COMMENT_NO, R.REPORTER_NO, R.REPORT_REASON, R.CREATED_AT, R.REPORT_STATUS, REP.USER_ID AS REPORTER_ID, COALESCE(AU.USER_ID, CU.USER_ID) AS AUTHOR_ID, CM.COMMENT_CONTENT, COALESCE(CO.USER_NO, CM.USER_NO) AS AUTHOR_NO FROM REPORT_TBL R LEFT JOIN USER_TBL REP ON R.REPORTER_NO = REP.USER_NO LEFT JOIN COMMENT_TBL CM ON R.COMMENT_NO = CM.COMMENT_NO LEFT JOIN COMMUNITY_TBL CO ON R.COMMUNITY_NO = CO.COMMUNITY_NO LEFT JOIN USER_TBL CU ON CO.USER_NO = CU.USER_NO LEFT JOIN USER_TBL AU ON CM.USER_NO = AU.USER_NO
R.REPORT_STATUS = #{status}
ORDER BY R.CREATED_AT DESC

mapper.update:
UPDATE COMMUNITY_TBL
SET DELETE_YN = 'Y'
WHERE COMMUNITY_NO = #{communityNo}

UPDATE COMMENT_TBL
SET DELETE_YN = 'Y'
WHERE COMMENT_NO = #{commentNo}
